<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { AudioLines, Braces, FileText, Image, MessageSquare, Plus, Search, Sparkles, Wrench } from 'lucide-vue-next'
import AppDialog from '../AppDialog.vue'
import ContextTypeEditor from './ContextTypeEditor.vue'
import { typeLabel } from '../../contextEngine'
import type { ContextType } from '@zedflow/sdk'
import { contextSourceCategories, contextSourceStyle, contextSourceTypeId, contextTypeDependencies, resolveSourceType, sameContextType, type ContextSourceEntry } from '../../contextSources'
const open = defineModel<boolean>('open', { required: true })
const props = defineProps<{ entries: ContextSourceEntry[]; requirements: Record<string, ContextType>; types: Record<string, ContextType>; loading?: boolean; error?: string }>()
const emit = defineEmits<{ add: [entries: ContextSourceEntry[]]; custom: [name: string, type: ContextType]; retry: []; explore: [] }>()
const search = ref(''), category = ref('all'), selected = ref<string[]>([]), customOpen = ref(false), customName = ref(''), customType = ref<ContextType>({ kind: 'record', fields: {} }), customError = ref('')
const entries = computed(() => props.entries.filter(entry => (category.value === 'all' || entry.category === category.value) && `${entry.label} ${entry.id} ${entry.origin} ${entry.providers.join(' ')} ${JSON.stringify(entry.types)} ${JSON.stringify(entry.type)}`.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
const selection = computed(() => props.entries.filter(entry => selected.value.includes(entry.id) && !unavailable(entry)))
function conflict(entry: ContextSourceEntry) { return Object.entries(contextTypeDependencies(entry.type, entry.types)).some(([name, type]) => props.types[name] && !sameContextType(props.types[name], type)) }
function alreadyDeclared(entry: ContextSourceEntry) { return Object.values(props.requirements).some(type => sameContextType(type, entry.type)) && !conflict(entry) }
function unavailable(entry: ContextSourceEntry) { return conflict(entry) || alreadyDeclared(entry) }
function fields(entry: ContextSourceEntry) { const type = resolveSourceType(entry.type, entry.types); return type.kind === 'record' ? Object.keys(type.fields).join(' · ') || 'Objet sans champs' : typeLabel(type) }
function provenance(entry: ContextSourceEntry) { return entry.providers.length > 1 ? `${entry.providers.length} provenances` : entry.providers[0] || entry.origin }
function icon(entry: ContextSourceEntry) { return entry.category === 'tools' ? Wrench : entry.category === 'documents' ? FileText : entry.category === 'messages' ? (/model|modèle/i.test(entry.label) ? Sparkles : MessageSquare) : entry.category === 'media' ? (/audio/i.test(entry.label) ? AudioLines : Image) : Braces }
function add() { emit('add', selection.value); open.value = false }
function custom() { const name = customName.value.trim(); if (!name || Object.hasOwn(props.types, name)) { customError.value = 'Choisissez un nom de type unique.'; return } emit('custom', name, customType.value); open.value = false }
watch(open, value => { if (value) { search.value = ''; category.value = 'all'; selected.value = []; customOpen.value = false; customName.value = ''; customType.value = { kind: 'record', fields: {} }; customError.value = '' } })
</script>
<template>
  <AppDialog v-model:open="open" title="Ajouter des types de sources" description="Types connus du workspace et de Zedflow. Le flow fournira les valeurs." wide>
    <section class="ctx-source-gallery">
      <label class="ctx-gallery-search"><Search :size="15"/><input v-model="search" aria-label="Rechercher un type ou un champ" placeholder="Rechercher un type ou un champ…"/></label>
      <nav class="ctx-gallery-categories" aria-label="Catégories de sources"><button v-for="item in contextSourceCategories" :key="item.id" type="button" :aria-pressed="category === item.id" @click="category = item.id">{{ item.label }}</button></nav>
      <p v-if="loading" class="ctx-gallery-status" role="status">Chargement des types des catalogues et des flows…</p>
      <p v-if="error" class="ctx-gallery-error" role="alert">{{ error }} <button type="button" @click="emit('retry')">Réessayer</button></p>
      <div class="ctx-gallery-grid" aria-label="Types de sources disponibles">
        <label v-for="entry in entries" :key="entry.id" class="ctx-gallery-type" :class="{ selected: selected.includes(entry.id), unavailable: unavailable(entry) }" :style="contextSourceStyle(contextSourceTypeId(entry.type))" :title="`${entry.origin}${entry.providers.length ? ' · Fourni par : ' + entry.providers.join(', ') : ''}`">
          <span class="ctx-gallery-icon"><component :is="icon(entry)" :size="20"/></span><span class="ctx-gallery-type-text"><strong>{{ entry.label }}</strong><small>{{ fields(entry) }}</small><span class="ctx-gallery-origin">{{ conflict(entry) ? 'Schéma différent dans ce brouillon' : alreadyDeclared(entry) ? 'Déjà déclaré' : provenance(entry) }}</span></span>
          <input v-model="selected" type="checkbox" :value="entry.id" :disabled="unavailable(entry)" :aria-label="`Sélectionner ${entry.label}`"/>
        </label>
      </div>
      <p v-if="!entries.length && !loading" class="ctx-gallery-status">Aucun type ne correspond à cette recherche.</p>
      <details class="ctx-gallery-custom" :open="customOpen" @toggle="customOpen = ($event.target as HTMLDetailsElement).open"><summary>Définir un type personnalisé</summary><label>Nom du type<input v-model="customName" aria-label="Nom du type personnalisé" placeholder="Ex. RésultatRecherche"/></label><ContextTypeEditor v-model="customType" :names="Object.keys(types)" label="Schéma du type personnalisé"/><p v-if="customError" role="alert" class="ctx-gallery-error">{{ customError }}</p><button type="button" @click="custom"><Plus :size="13"/>Déclarer ce type</button></details>
      <p class="ctx-gallery-note">Un type disponible ici n’est pas garanti par chaque flow. Déclarer une source ne l’ajoute pas encore au contexte.</p>
      <footer><button type="button" class="ctx-gallery-explore" @click="open = false; emit('explore')">Explorer les catalogues de types</button><span>{{ selection.length }} type{{ selection.length > 1 ? 's' : '' }} sélectionné{{ selection.length > 1 ? 's' : '' }}</span><button type="button" @click="open = false">Annuler</button><button type="button" class="ctx-gallery-primary" :disabled="!selection.length" @click="add">Ajouter {{ selection.length || '' }} type{{ selection.length > 1 ? 's' : '' }}</button></footer>
    </section>
  </AppDialog>
</template>
<style scoped>
:global(.app-dialog.wide:has(>.ctx-source-gallery)){width:min(860px,calc(100vw - 32px))}
.ctx-source-gallery{display:flex;flex-direction:column;gap:16px;font-size:12px;max-height:calc(100dvh - 180px);min-height:0}.ctx-gallery-search{display:flex;align-items:center;gap:9px;border:1px solid var(--border,#35353a);border-radius:6px;padding:0 11px;min-height:37px;color:var(--muted,#a0a0a0)}.ctx-gallery-search input{flex:1;min-width:0;border:0!important;background:none!important;padding:8px 0!important;font:inherit;outline:none!important;color:var(--text,#ececf0)}.ctx-gallery-search:focus-within{outline:2px solid var(--text,#eee);outline-offset:2px}.ctx-gallery-categories{display:flex;gap:6px;flex-wrap:wrap;padding:0}.ctx-gallery-categories button{width:auto;flex:none;padding:6px 9px;min-height:30px;font-size:11px;border:1px solid var(--border,#333);border-radius:5px;background:transparent;color:var(--muted,#aaa)}.ctx-gallery-categories button[aria-pressed=true]{background:var(--surface-raised,#343439);color:var(--text,#eee)}.ctx-gallery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;overflow:auto;min-height:0;max-height:340px;padding:2px}.ctx-gallery-type{display:flex;align-items:center;gap:10px;position:relative;min-width:0;min-height:76px;padding:10px 26px 10px 11px;border:1px solid var(--border,#35353a);border-radius:7px;cursor:pointer;background:var(--surface,#202024)}.ctx-gallery-type.selected{border-color:color-mix(in srgb,var(--ctx-source-color) 65%,var(--border,#333));background:color-mix(in srgb,var(--ctx-source-color) 6%,var(--surface,#202024))}.ctx-gallery-type:hover:not(.unavailable){border-color:var(--ctx-source-color)}.ctx-gallery-type:focus-within{outline:2px solid var(--ctx-source-color);outline-offset:1px}.ctx-gallery-type.unavailable{opacity:.55;cursor:default}.ctx-gallery-type input{position:absolute;top:10px;right:9px;accent-color:var(--ctx-source-color);width:14px;height:14px;margin:0}.ctx-gallery-icon{display:grid;place-items:center;flex:0 0 34px;height:36px;border-radius:6px;background:color-mix(in srgb,var(--ctx-source-color) 14%,transparent);color:var(--ctx-source-color)}.ctx-gallery-type-text{min-width:0;display:grid;gap:5px}.ctx-gallery-type strong{font-size:11px;font-weight:550;line-height:1.3}.ctx-gallery-type small,.ctx-gallery-origin{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted,#a0a0a0);font-size:10px;line-height:1.3}.ctx-gallery-origin{font-size:9px;opacity:.8}.ctx-gallery-note{margin:0;line-height:1.6;color:var(--muted,#a0a0a0);font-size:11px}.ctx-gallery-custom{font-size:11px;color:var(--muted,#aaa)}.ctx-gallery-custom summary{cursor:pointer}.ctx-gallery-custom[open]{display:grid;gap:8px;max-height:230px;overflow:auto}.ctx-gallery-custom label{display:grid;gap:5px;margin:10px 0}.ctx-gallery-custom button{display:inline-flex;align-items:center;gap:5px;margin:8px 0 0}.ctx-gallery-status{color:var(--muted,#aaa);font-size:11px;margin:0}.ctx-gallery-error{color:var(--danger,#e89b92);font-size:11px;margin:0}.ctx-source-gallery footer{display:flex;align-items:center;gap:8px;padding-top:4px}.ctx-source-gallery footer span{margin-left:auto;white-space:nowrap;color:var(--muted,#a0a0a0);font-size:10px}.ctx-source-gallery footer button{white-space:nowrap;padding:7px 10px;font-size:11px}.ctx-source-gallery .ctx-gallery-explore{border:0;background:none;padding-left:0;color:var(--link,#8ab6e7);font-size:10px}.ctx-source-gallery .ctx-gallery-primary{background:var(--text,#e9e9ed);color:var(--bg,#18181b);font-weight:600;border-color:transparent}.ctx-gallery-primary:disabled{opacity:.4}.ctx-gallery-custom :deep(input),.ctx-gallery-custom :deep(select){min-width:0}
@media(max-width:720px){.ctx-gallery-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ctx-source-gallery footer{flex-wrap:wrap}.ctx-source-gallery .ctx-gallery-explore{width:100%;text-align:left}.ctx-source-gallery footer span{margin-left:0;margin-right:auto}}
@media(max-width:430px){.ctx-gallery-grid{grid-template-columns:1fr}.ctx-source-gallery{max-height:calc(100dvh - 155px)}}
</style>
